	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		ComplianceProgram
	 */
		public ComplianceProgram createComplianceProgram( CreateComplianceProgramCommand command ) {

		ComplianceProgram entity = new ComplianceProgram();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setComplianceProgramId( command.getComplianceProgramId() );
            entity.setName( command.getName() );
            entity.setFramework( command.getFramework() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of ComplianceProgram {0} ", entity.toString() );

		return entity;
	}

