	/**
	 * Method to retrieve the ComplianceProgram via ComplianceProgramFetchOneSummary
	 * @param 	summary ComplianceProgramFetchOneSummary
	 * @return 	ComplianceProgramFetchOneResponse
	 */
	public ComplianceProgram getComplianceProgram( ComplianceProgramFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "ComplianceProgramFetchOneSummary arg cannot be null" );

		ComplianceProgram entity = null;
		UUID id = summary.getComplianceProgramId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a ComplianceProgram using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


